NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Philippians'

CHAPTERS = {
    1: {
        1: 'Pavel in Timótej, služabnika Jezusa Kristusa, vsem svetim v Kristusu Jezusu, ki so v Filípih, z duhovnimi nadzorniki in pomočniki [Božjih] služabnikov:',
        2: '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹',
        3: 'Svojemu Bogu se zahvaljujem vsakič, ko se vas spominjam,',
        4: 'vedno v vsaki svoji molitvi z radostjo prosim za vas vse,',
        5: 'zaradi vaše družbe v evangeliju, od prvega dne do sedaj;',
        6: 'ker sem prepričan o tej sami stvari, da on, ki je v vas začel dobro delo, ga bo opravil do dneva Jezusa Kristusa.',
        7: 'Prav tako je zame primerno, da tako mislim o vas vseh, ker vas imam v svojem srcu; glede na to, da ste vi vsi udeleženci moje milosti, tako v mojih verigah kakor v obrambi in potrjevanju evangelija.',
        8: 'Kajti Bog je moja priča, kako silno hrepenim po vas vseh v notranjostih Jezusa Kristusa.',
        9: 'In molim to, da bo vaša ljubezen lahko še bolj in bolj obilna v spoznanju in v vsaki razsodbi;',
        10: 'da boste lahko presojali stvari, ki so odlične; da boste lahko iskreni in brez pohujšanja do Kristusovega dne;',
        11: 'izpolnjeni s sadovi pravičnosti, ki so po Jezusu Kristusu, v slavo in hvalo Božjo.',
        12: 'Toda, [da] bi razumeli, bratje, da so stvari, ki so se mi zgodile, toliko bolj izpadle v pospeševanje evangelija;',
        13: 'tako da so moje vezi v Kristusu razpoznavne po vsej palači in po vseh drugih krajih;',
        14: 'in mnogi izmed bratov v Gospodu so z mojimi vezmi povečali samozavest, da so mnogo pogumneje, brez strahu, govorili besedo.',
        15: 'Nekateri zares oznanjajo Kristusa celó iz zavisti in prepira, nekateri pa tudi iz dobre volje;',
        16: 'nekdo oznanja Kristusa iz spora, ne iskreno, ker misli, da mojim vezem dodaja stisko,',
        17: 'toda drug iz ljubezni, vedoč, da sem določen za obrambo evangelija.',
        18: 'Kaj torej? Vseeno, vsak način, bodisi s pretvezo ali z resnico, Kristus se oznanja; in v tem se veselim, da in veselil se bom.',
        19: 'Kajti vem, da se bo to, po vaših molitvah in oskrbi Duha Jezusa Kristusa, obrnilo k rešitvi moje duše,',
        20: 'glede na moje iskreno pričakovanje in moje upanje, da v ničemer ne bom osramočen, temveč, da bo z vso srčnostjo, kot vedno, tako tudi sedaj, Kristus poveličan v mojem telesu, bodisi bo to z življenjem ali s smrtjo.',
        21: 'Kajti zame je živeti Kristus in umreti je dobiček.',
        22: 'Toda če živim v mesu, je to sad mojega truda; vendar ne vem, kaj bi izbral.',
        23: 'Kajti v škripcu sem med dvema, ker hrepenim oditi in biti s Kristusom; kar je veliko bolje,',
        24: 'pa vendar je zaradi vas bolj potrebno ostati v mesu.',
        25: 'In ker imam to zaupanje, vem, da bom zaradi vašega napredovanja in veselja vere ostal in nadaljeval z vami vsemi;',
        26: 'da bo vaše veselje v Jezusu Kristusu lahko bolj obilno zaradi mene, z mojim ponovnim prihodom k vam.',
        27: 'Samo vaše vedênje naj bo, kakor se to spodobi Kristusovemu evangeliju, da bom bodisi prišel in vas videl, bodisi [da] bom odsoten, lahko slišal o vaših zadevah, da trdno stojite v enem duhu, enega mišljenja in si skupaj prizadevate za vero evangelija;',
        28: 'in v ničemer prestrašeni od svojih nasprotnikov, kar je njim očiten simbol pogube, toda vam rešitev duš in to od Boga.',
        29: '§ Kajti zaradi Kristusa vam je dano, da ne samo verujete vanj, ampak da zaradi njega tudi trpite;',
        30: 'in imate isti boj, ki ste ga videli v meni in sedaj slišite, da je v meni.',
    },
    2: {
        1: 'Če obstaja torej kakršnakoli tolažba v Kristusu, če kakršnakoli tolažba ljubezni, če kakršnakoli družba Duha, če kakršnakoli čustva in usmiljenja,',
        2: 'izpolnite moje veselje, da ste istih misli in imate isto ljubezen, da ste soglasni, enega mišljenja.',
        3: 'Naj se nič ne stori zaradi prepira ali ošabnosti, temveč naj vsak v skromnosti mišljenja bolj upošteva drugega kakor sebe.',
        4: 'Ne glejte vsakdo na svoje stvari, temveč vsakdo tudi na stvari drugih.',
        5: 'V vas naj bo to mišljenje, ki je bilo tudi v Kristusu Jezusu,',
        6: '§ ki je, četudi v Božji podobi, mislil, da ni rop, da bi bil enak z Bogom;',
        7: 'temveč je samega sebe naredil brez slôvesa in si privzel obliko služabnika in bil narejen po človeški podobnosti;',
        8: 'in po videzu zaznan kakor moški, je samega sebe ponižal in postal pokoren do smrti, celó smrti na križu.',
        9: 'Zatorej ga je Bog tudi visoko povišal in mu dal ime, ki je nad vsakim imenom,',
        10: 'da naj bi ob imenu Jezus pokleknilo vsako koleno, od stvari na nebu in stvari na zemlji ter stvari pod zemljo;',
        11: 'ter da bi vsak jezik priznal, da je Jezus Kristus Gospod, v slavo Boga Očeta.',
        12: 'Zatorej, moji ljubljeni, kakor ste vedno ubogali, ne kakor samo v moji prisotnosti, temveč veliko bolj zdaj, v moji odsotnosti, s strahom in trepetom uresničite svojo lastno rešitev duše.',
        13: 'Kajti Bog je, ki deluje v vas oboje, da hočete in da delate iz njegovega dobrega zadovoljstva.',
        14: 'Vse stvari delajte brez mrmranj in razpravljanj,',
        15: 'da boste lahko brez krivde in neškodljivi Božji sinovi, brez oštevanja v sredi sprijenega in sprevrženega naroda, med katerim sijete kakor luči na svetu;',
        16: 'držeč se besede življenja, da se bom na Kristusov dan lahko veselil, da nisem zaman tekel niti [se nisem] zaman trudil.',
        17: 'Da, in če bi bil darovan na žrtev in službo vaše vere, se radostim in se z vami vsemi veselim.',
        18: 'Zaradi istega razloga se tudi vi veselite in razveseljujte z menoj.',
        19: 'Toda zaupam v Gospoda Jezusa, da v kratkem pošljem k vam Timóteja, da bom tudi jaz, ko izvem vaše stanje, lahko dobro potolažen.',
        20: 'Kajti nimam nobenega človeka istih misli, ki bo naravno skrbel za vaše stanje.',
        21: 'Kajti vsi iščejo svoje lastno, ne [pa] stvari, ki so Jezusa Kristusa.',
        22: 'Vendar poznate dokaz o njem, da je z menoj služil v evangeliju kakor sin z očetom.',
        23: 'Njega se torej nadejam poslati tako kmalu, kot bom videl, kako bo z menoj.',
        24: 'Toda zaupam v Gospoda, da bom kmalu prišel tudi sam.',
        25: 'Vendar se mi je zdelo potrebno poslati k vam Epafrodita, mojega brata in družabnika v trudu in soborca, toda vašega odposlanca in tega, ki je služil mojim potrebam.',
        26: 'Kajti hrepenel je po vas vseh in bil poln potrtosti; zato ker ste slišali, da je bil bolan.',
        27: 'Kajti zares je bil bolan, blizu smrti, toda Bog se ga je usmilil; in ne samo njega, ampak tudi mene, da ne bi imel bridkost na bridkost.',
        28: 'Poslal sem ga torej bolj hitro, da ko ga boste ponovno videli, se boste lahko razveselili in da bom jaz lahko manj žalosten.',
        29: 'Sprejmite ga torej v Gospodu z vsem veseljem; in take imejte v časti;',
        30: 'ker je bil zaradi Kristusovega dela blizu smrti, ne oziraje se na svoje življenje, da dopolni pomanjkanje vašega služenja do mene.',
    },
    3: {
        1: 'Končno, moji bratje, veselite se v Gospodu. Da vam pišem iste stvari, meni zares ni nadležno, toda za vas je to varno.',
        2: '§ Pazite se psov, pazite se zlih delavcev, pazite se razkola.',
        3: '§ Kajti mi smo obreza, ki obožujemo Boga v duhu in se veselimo v Kristusu Jezusu in nimamo zaupanja v meso.',
        4: 'Čeprav bi tudi jaz lahko imel zaupanje v meso. Če katerikoli drug človek misli, da ima [kaj], glede česar bi lahko zaupal v meso, jaz bolj:',
        5: 'obrezan osmi dan, iz Izraelove rase, iz Benjaminovega rodu, Hebrejec izmed Hebrejcev, glede postave farizej,',
        6: 'glede gorečnosti sem preganjal cerkev, glede pravičnosti, ki je po postavi, brez krivde.',
        7: 'Toda te stvari, ki so bile zame dobiček, te sem štel izgubo za Kristusa.',
        8: '§ Da, nedvomno in vse stvari štejem le za izgubo zaradi odličnosti spoznanja Kristusa Jezusa, svojega Gospoda, za katerega sem pretrpel izgubo vseh stvari in jih štejem le za iztrebek, da lahko pridobim Kristusa,',
        9: 'in najden bom v njem, ne ker bi imel svojo lastno pravičnost, ki je iz postave, temveč to, ki je po Kristusovi veri, pravičnost, ki je od Boga, po veri;',
        10: 'da bi lahko spoznal njega in moč njegovega vstajenja in udeležbo njegovih trpljenj in postal podoben njegovi smrti;',
        11: 'če na kakršenkoli način lahko dospem do vstajenja mrtvih.',
        12: 'Ne da bi že dospel ali bi bil že popoln; vendar si prizadevam za tem, če bi lahko željno vzel to, zaradi česar sem tudi jaz željno vzet od Kristusa Jezusa.',
        13: 'Bratje, ne štejem se, da sem željno vzet, toda delam to eno stvar in pozabljam te stvari, ki so zadaj in se iztegujem k tem stvarem, ki so spredaj;',
        14: 'pritiskam proti cilju zaradi nagrade visoke poklicanosti od Boga v Kristusu Jezusu.',
        15: 'Bodimo torej, kolikor nas je popolnih, takega mišljenja; in če ste v katerikoli stvari drugače misleči, vam bo Bog razodel še to.',
        16: '§ Pa vendar, kateri smo že dospeli, živimo po istem načelu, mislimo isto stvar.',
        17: 'Bratje, bodite skupaj moji posnemovalci in zapomnite si tiste, ki živijo tako, kakor imate nas za zgled.',
        18: '(Kajti mnogi živijo, o katerih sem vam pogosto povedal in vam sedaj govorim jokaje, da so sovražniki Kristusovega križa;',
        19: 'katerih konec je uničenje, katerih Bog je njihov trebuh in katerih slava je v njihovi sramoti, ki mislijo zemeljske stvari.)',
        20: 'Kajti naše državljanstvo je v nebesih, od koder tudi pričakujemo Odrešenika, Gospoda Jezusa Kristusa,',
        21: 'ki bo, glede na delovanje, s katerim si je zmožen k sebi podjarmiti celó vse stvari, spremenil naša nizkotna telesa, da bodo oblikovana podobno njegovemu veličastnemu telesu.',
    },
    4: {
        1: 'Zato, moji bratje, srčno ljubljeni in zaželeni, moja radost in krona, tako stojte trdno v Gospodu, moji srčno ljubljeni.',
        2: 'Rotim Evodíjo in rotim Sintího, da bosta istega mišljenja v Gospodu.',
        3: 'In prosim tudi tebe, resnični soborec, pomagaj tema ženskama, ki sta se z menoj trudili v evangeliju; tudi s Klemnom in z drugimi mojimi sodelavci, katerih imena so v knjigi življenja.',
        4: 'Nenehno se veselite v Gospodu. In ponovno pravim: ›Veselite se.‹',
        5: 'Naj bo vaša zmernost znana vsem ljudem. Gospod je blizu.',
        6: 'Ne vznemirjate se in ne skrbite glede ničesar, temveč naj bodo v vsaki stvari vaše želje razglašene Bogu z molitvijo in ponižno prošnjo, z zahvaljevanjem.',
        7: 'In Božji mir, ki presega vse razumevanje, bo varoval vaša srca in mišljenja po Kristusu Jezusu.',
        8: 'Končno, bratje, katerekoli stvari so resnične, katerekoli stvari so iskrene, katerekoli stvari so pravične, katerekoli stvari so čiste, katerekoli stvari so očarljive, katerekoli stvari so na dobrem glasu; če obstaja kakršnakoli moč in če obstaja kakršnakoli hvala, mislite na te stvari.',
        9: 'Stvari, ki ste se jih tako naučili, kakor sprejeli in slišali ter videli na meni, te izvršujte; in z vami bo Bog miru.',
        10: 'Toda silno sem se razveselil v Gospodu, da je vaša skrbnost do mene sedaj končno ponovno vzcvetela; v čemer ste tudi bili skrbni, toda manjkala vam je priložnost.',
        11: 'Ne da govorim glede na pomanjkanje, kajti naučil sem se, v kakršnemkoli stanju sem, biti s tem zadovoljen.',
        12: 'Vem oboje, kako je biti ponižen in vem, kako je biti bogat; povsod in v vseh stvareh sem poučen, tako biti sit kakor biti lačen, tako biti bogat kakor prenašati pomanjkanje.',
        13: 'Vse stvari lahko storim v Kristusu, ki me krepi.',
        14: 'Vendar ste dobro storili, da ste soudeleženi pri moji stiski.',
        15: 'Torej vi Filipljani veste tudi, da na začetku evangelija, ko sem odšel iz Makedonije, nobena cerkev ni sodelovala z menoj glede dajanja in sprejemanja, razen vas samih.',
        16: 'Kajti celó v Tesaloníko ste večkrat poslali za mojo nujno potrebo.',
        17: 'Ne, ker [bi si] želel daru, temveč si želim sad, da bo obilen na vaš račun.',
        18: 'Toda imam vse in obilo; sem poln, ker sem od Epafrodita prejel stvari, ki so bile poslane od vas, dišavo sladkega vonja, sprejemljivo žrtvovanje, všečno Bogu.',
        19: '§ Toda moj Bog bo preskrbel vse vaše potrebe, glede na svoja bogastva, v slavi, po Jezusu Kristusu.',
        20: 'Torej Bogu in našemu Očetu bodi slava na veke vekov. Amen.',
        21: 'Pozdravite vsakega svetega v Kristusu Jezusu. Pozdravljajo vas bratje, ki so z menoj.',
        22: 'Pozdravljajo vas vsi sveti, predvsem tisti, ki so iz cesarjeve družine.',
        23: 'Milost našega Gospoda Jezusa Kristusa bodi z vami vsemi. Amen. [To je bilo napisano Filipljanom iz Rima po Epafroditu.]',
    },
}
